// Get random keywords
const getRandomKeywords = (count = 2) => {
  const shuffled = [...KEYWORDS_PAKISTAN].sort(() => 0.5 - Math.random());
  return shuffled.slice(0, Math.min(count, KEYWORDS_PAKISTAN.length));
};

// const keywords = getRandomKeywords(2);
const keywords = ["lahore", "kurta"]

return [{
  json: {
    keywords: keywords,
    countries: ['PK'],
    minAdsPerPage: 4,
    daysLookback: 7,
    maxAdsPerKeyword: 200,
    apiVersion: 'v25.0',
    spreadsheetId: '1pBYVkOrzarunXq2XhVgUOYOBJuVag3Tk2mjG-WQASTI',
    sheetName: 'CTWA Leads'
  }
}];

const items = $input.all();
const cutoffDate = new Date();
cutoffDate.setDate(cutoffDate.getDate() - 7);
const cutoffDateStr = cutoffDate.toISOString().split('T')[0];

let allAds = [];

// Combine ads from both keywords
items.forEach(item => {
  if (item.json && item.json.data && Array.isArray(item.json.data)) {
    const recentAds = item.json.data.filter(ad => {
      const startDate = ad.ad_delivery_start_time || '';
      return startDate && startDate.substring(0, 10) >= cutoffDateStr;
    });
    allAds = allAds.concat(recentAds);
  }
});

return allAds.map(ad => ({ json: ad }));

const items = $input.all();

// Pakistani cities for detection
const PAKISTANI_CITIES = [
  'karachi', 'lahore', 'islamabad', 'rawalpindi', 'faisalabad',
  'multan', 'peshawar', 'quetta', 'sialkot', 'gujranwala',
  'hyderabad', 'sukkur', 'bahawalpur', 'gujrat', 'mardan'
];

const hasWhatsAppIndicator = (ad) => {
  // Check link captions
  const linkCaptions = ad.ad_creative_link_captions || [];
  if (Array.isArray(linkCaptions)) {
    for (const caption of linkCaptions) {
      if (caption && typeof caption === 'string' && caption.toLowerCase().includes('api.whatsapp.com')) {
        return true;
      }
    }
  }

  return false;
};

const extractAdCreativeText = (ad) => {
  const creativeParts = [];
  const bodies = ad.ad_creative_bodies || [];
  if (Array.isArray(bodies)) {
    bodies.forEach(body => {
      if (body && typeof body === 'string') {
        creativeParts.push(body.trim());
      }
    });
  }
  return creativeParts.join(' | ').substring(0, 1000);
};

const isLikelyPakistani = (pageName, adText) => {
  const pageLower = (pageName || '').toLowerCase();
  const adLower = (adText || '').toLowerCase();

  // Check cities
  for (const city of PAKISTANI_CITIES) {
    if (pageLower.includes(city) || adLower.includes(city)) {
      return true;
    }
  }

  // Check other indicators
  if (pageLower.includes('pakistan') || pageLower.includes(' pk ')) return true;
  if (adLower.includes('pkr') || adLower.includes('rs.') || adLower.includes('rupees')) return true;
  if (adLower.includes('pakistan')) return true;

  return true; // Default to true for Pakistan-targeted ads
};

// Group by page
const pageMap = new Map();

items.forEach(item => {
  const ad = item.json;
  const pageId = ad.page_id;
  if (!pageId) return;

  if (!pageMap.has(pageId)) {
    pageMap.set(pageId, {
      page_id: pageId,
      page_name: ad.page_name || 'Unknown',
      ads: [],
      has_whatsapp: false,
      first_seen: ad.ad_delivery_start_time || '',
      last_seen: ad.ad_delivery_start_time || '',
      sample_ad_creative: ''
    });
  }

  const page = pageMap.get(pageId);
  page.ads.push(ad);

  if (hasWhatsAppIndicator(ad)) {
    page.has_whatsapp = true;
    if (!page.sample_ad_creative) {
      page.sample_ad_creative = extractAdCreativeText(ad);
    }
  }

  // Update dates
  const startDate = ad.ad_delivery_start_time || '';
  if (startDate) {
    if (!page.first_seen || startDate < page.first_seen) {
      page.first_seen = startDate;
    }
    if (!page.last_seen || startDate > page.last_seen) {
      page.last_seen = startDate;
    }
  }
});

// Filter and format results
const minAdsPerPage = 4;
const results = [];

for (const [pageId, data] of pageMap) {
  const adCount = data.ads.length;
  const adCreative = data.sample_ad_creative || 'No creative text available';

  if (adCount >= minAdsPerPage && data.has_whatsapp) {
    if (isLikelyPakistani(data.page_name, adCreative)) {
      results.push({
        business_name: data.page_name,
        page_link: `https://fb.com/${pageId}`,
        ad_creative_bodies: adCreative,
        active_ads_count: adCount,
        first_seen: data.first_seen,
        last_seen: data.last_seen
      });
    }
  }
}

return results.map(lead => ({ json: lead }));

// Get existing data from Google Sheets (would need a prior node to fetch this)
// For now, return all leads as new
const items = $input.all();

// Create sets for deduplication (in a real workflow, you'd fetch existing data first)
const existingBusinesses = new Set();
const existingPageLinks = new Set();

const uniqueLeads = [];

items.forEach(item => {
  const lead = item.json;
  const business = (lead.business_name || '').trim();
  const pageLink = (lead.page_link || '').trim();

  // Simple check - in production, you'd have previous data
  if (!existingBusinesses.has(business) && !existingPageLinks.has(pageLink)) {
    uniqueLeads.push(lead);
    existingBusinesses.add(business);
    existingPageLinks.add(pageLink);
  }
});

// Format for Google Sheets
return uniqueLeads.map(lead => ({
  json: {
    business_name: lead.business_name,
    page_link: lead.page_link,
    ad_creative: (lead.ad_creative_bodies || '').substring(0, 500) + (lead.ad_creative_bodies?.length > 500 ? '...' : ''),
    active_ads: lead.active_ads_count,
    start_date: (lead.first_seen || '').substring(0, 10),
    whatsapp_number: '', // Empty for manual entry
    status: '' // Empty for manual entry
  }
}));

const items = $input.all();
const savedCount = items.length;

const summary = {
  timestamp: new Date().toISOString(),
  saved_count: savedCount,
  message: savedCount > 0 ? `Saved ${savedCount} new leads` : 'No new leads found'
};

// Add random delay between 45-90 seconds before next run
const delaySeconds = Math.floor(Math.random() * 45) + 45;
console.log(`Waiting ${delaySeconds} seconds before next run...`);

return [{
  json: summary
}];
